#!/usr/bin/env python3
"""Quality gate for projects generated by the Neway Commerce OS skill.

This script is the machine-readable half of the contract in SKILL.md
("HARD GATES"). Every gate below maps 1:1 to a rule there — if you change a
rule in SKILL.md, change the gate here in the same commit, otherwise the
contract and the enforcement drift apart.

Usage
-----
    python validate_generated_project.py <project_dir> [options]

Options
-------
    --template          Validate `templates/base` itself. Placeholder tokens
                        (__SITE_NAME__ etc.) are allowed in this mode.
    --lang zh-CN|en     Expected UI language. Drives the index.html lang check.
                        Default: zh-CN
    --currency CNY|USD  Expected currency. Blocks the other symbol in source.
                        Default: CNY
    --check-images      Also HEAD-request remote image URLs (needs network).
    --json              Emit a JSON report instead of the text report.

Exit code is 0 only when there are zero errors. Warnings never fail the build
but must be reviewed before delivery.
"""

from __future__ import annotations

import argparse
import json
import re
import urllib.request
from pathlib import Path

# --------------------------------------------------------------------------- #
# Gate definitions
# --------------------------------------------------------------------------- #

REQUIRED_FILES = [
    "package.json",
    "index.html",
    "tailwind.config.js",
    "postcss.config.js",
    "vite.config.ts",
    "tsconfig.json",
    ".env.example",
    "edgeone.json",
    "src/main.tsx",
    "src/App.tsx",
    "src/styles.css",
    "src/utils/format.ts",
    "src/components/Navbar.tsx",
    "src/components/Footer.tsx",
    "src/components/ProductCard.tsx",
    "src/components/CartDrawer.tsx",
    "src/components/AIChatWidget.tsx",
    "src/pages/HomePage.tsx",
    "src/pages/ShopPage.tsx",
    "src/pages/ProductPage.tsx",
    "src/pages/CartPage.tsx",
    "src/pages/CheckoutPage.tsx",
    "src/pages/WishlistPage.tsx",
    "src/pages/AdminPage.tsx",
    "src/types/index.ts",
    "src/data/products.ts",
    "src/store/cartStore.ts",
]

# Accepted naming variants (any one of the group satisfies the gate)
FILE_VARIANTS = [
    ["src/styles.css", "src/index.css"],
]

DEPLOYMENT_FILES = [
    "functions/api/products.ts",
    "functions/api/checkout.ts",
    "functions/api/assistant.ts",
    "functions/node/stripe-webhook.ts",
]

FORBIDDEN_FILES = [
    "src/pages/AccountPage.tsx",
    "src/components/AiConcierge.tsx",
    "src/data/products.json",
    "src/lib/api.ts",
]

PLACEHOLDER_TOKENS = ["__SITE_NAME__", "__BRAND_NAME__", "__SITE_SLUG__", "__PROMPT__"]

# Copy that signals the template was never filled in
PLACEHOLDER_COPY = [
    "Product One",
    "Product Two",
    "Category A",
    "category-a",
    "Lorem ipsum",
    "Your Brand",
    "example.com",
    "TODO:",
    "FIXME",
]

# Product interface contract — must match SKILL.md "Product data contract"
REQUIRED_PRODUCT_FIELDS = [
    "id",
    "name",
    "nameEn",
    "brand",
    "category",
    "price",
    "images",
    "colors",
    "sizes",
    "description",
    "details",
    "tags",
    "material",
    "fit",
    "rating",
    "reviewCount",
    "isNew",
    "isSale",
]

# Cart store contract — must match the template's cartStore.ts
CART_STORE_MEMBERS = [
    "persist",
    "addItem",
    "removeItem",
    "updateQuantity",
    "clearCart",
    "itemCount",
    "total",
    "toggleCart",
]

REQUIRED_CSS_CLASSES = [
    "btn-primary",
    "btn-outline",
    "btn-ghost",
    "tag",
    "section-title",
    "section-subtitle",
    "input-field",
]

# Domain-neutral page indicators (regex, not literal substrings)
PAGE_INDICATORS = {
    "src/pages/HomePage.tsx": [
        (r"categories", "category banners"),
        (r"isNew", "new-arrivals section"),
        (r"ProductCard", "product grid"),
    ],
    "src/pages/ShopPage.tsx": [
        (r"sort", "sort control"),
        # \u7b5b\u9009 == the zh-CN word for "filter"; escaped so no literal
        # CJK text lives in this file (the check_skill_language.py gate).
        (r"filter|\u7b5b\u9009", "filter panel"),
        (r"'grid'|'list'", "grid/list toggle"),
        (r"useSearchParams", "URL-driven category tabs"),
    ],
    "src/pages/ProductPage.tsx": [
        (r"images\[", "image gallery"),
        (r"addItem", "add-to-cart"),
        (r"toggle\(", "wishlist toggle"),
        (r"related", "related products"),
    ],
    "src/pages/CheckoutPage.tsx": [
        (r"step", "multi-step flow"),
        (r"PROMO_CODES", "promo codes"),
        (r"clearCart", "cart clearing"),
    ],
}

SOURCE_SUFFIXES = {".ts", ".tsx", ".js", ".jsx", ".css", ".html", ".json", ".md"}
SCAN_DIRS = ["src", "functions"]
SCAN_FILES = ["index.html"]

EMOJI_RE = re.compile(
    "[\U0001f000-\U0001faff\U00002600-\U000027bf\U00002b00-\U00002bff\U0000fe0f\U00002190-\U000021ff]"
)
FONT_PX_RE = re.compile(r"text-\[(\d+)px\]")
CURRENCY_CONFLICT = {"CNY": re.compile(r"\$\s?\d"), "USD": re.compile(r"¥\s?\d")}
CATEGORY_KEY_RE = re.compile(r"\{\s*key:\s*'([^']+)'")
IMAGES_ARRAY_RE = re.compile(r"images:\s*\[(.*?)\]", re.DOTALL)


# --------------------------------------------------------------------------- #
# Helpers
# --------------------------------------------------------------------------- #


def iter_source_files(project_dir: Path, include_markdown: bool = False):
    for folder in SCAN_DIRS:
        base = project_dir / folder
        if not base.exists():
            continue
        for path in sorted(base.rglob("*")):
            if not path.is_file() or path.suffix not in SOURCE_SUFFIXES:
                continue
            if path.suffix == ".md" and not include_markdown:
                continue
            if path.name.endswith(".tsbuildinfo"):
                continue
            yield path
    for name in SCAN_FILES:
        path = project_dir / name
        if path.exists():
            yield path


def read(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except (UnicodeDecodeError, OSError):
        return ""


def line_of(text: str, index: int) -> int:
    return text.count("\n", 0, index) + 1


# --------------------------------------------------------------------------- #
# Gates
# --------------------------------------------------------------------------- #


def run_gates(project_dir: Path, args) -> tuple[list[str], list[str], list[dict]]:
    errors: list[str] = []
    warnings: list[str] = []
    gates: list[dict] = []

    def gate(gid: str, name: str, ok: bool, detail: list[str] | None = None, warn_only: bool = False):
        detail = detail or []
        gates.append(
            {
                "id": gid,
                "name": name,
                "status": "PASS" if ok else ("WARN" if warn_only else "FAIL"),
                "detail": detail,
            }
        )
        if ok:
            return
        (warnings if warn_only else errors).extend(detail or [f"{name}: failed"])

    # F — structure ---------------------------------------------------------
    missing = [f for f in REQUIRED_FILES if not (project_dir / f).exists()]
    gate("F-01", "required files present", not missing, [f"missing file: {m}" for m in missing])

    variant_missing = [g for g in FILE_VARIANTS if not any((project_dir / v).exists() for v in g)]
    gate("F-02", "style file variant present", not variant_missing, [f"missing one of: {g}" for g in variant_missing])

    deploy_missing = [f for f in DEPLOYMENT_FILES if not (project_dir / f).exists()]
    gate(
        "F-03",
        "deployment files present",
        not deploy_missing,
        [f"missing deployment file: {m}" for m in deploy_missing],
        warn_only=True,
    )

    leftovers = [f for f in FORBIDDEN_FILES if (project_dir / f).exists()]
    gate("F-04", "no template leftovers", not leftovers, [f"must be deleted: {f}" for f in leftovers])

    # P — placeholders ------------------------------------------------------
    if args.template:
        gate("P-01", "placeholder tokens resolved", True, [])
    else:
        hits = []
        for path in iter_source_files(project_dir, include_markdown=True):
            content = read(path)
            for token in PLACEHOLDER_TOKENS:
                if token in content:
                    hits.append(f"{path.relative_to(project_dir)}: unreplaced {token}")
        gate("P-01", "placeholder tokens resolved", not hits, hits)

    copy_hits = []
    for path in iter_source_files(project_dir, include_markdown=True):
        content = read(path)
        for phrase in PLACEHOLDER_COPY:
            if phrase in content:
                copy_hits.append(f"{path.relative_to(project_dir)}: placeholder copy '{phrase}'")
    gate("P-02", "placeholder copy replaced", not copy_hits, copy_hits)

    # G — design iron rules -------------------------------------------------
    emoji_hits = []
    for path in iter_source_files(project_dir):
        content = read(path)
        for m in EMOJI_RE.finditer(content):
            emoji_hits.append(f"{path.relative_to(project_dir)}:{line_of(content, m.start())} emoji '{m.group()}'")
    gate("G-01", "no emoji in UI source", not emoji_hits, emoji_hits)

    font_hits = []
    for path in iter_source_files(project_dir):
        content = read(path)
        for m in FONT_PX_RE.finditer(content):
            size = int(m.group(1))
            if size < 12:
                font_hits.append(
                    f"{path.relative_to(project_dir)}:{line_of(content, m.start())} {size}px is below the 12px floor"
                )
            elif size % 2 != 0:
                font_hits.append(f"{path.relative_to(project_dir)}:{line_of(content, m.start())} {size}px is odd")
    gate("G-02", "font sizes even and >= 12px", not font_hits, font_hits)

    money_re = CURRENCY_CONFLICT[args.currency]
    other = "USD" if args.currency == "CNY" else "CNY"
    money_hits = []
    for path in iter_source_files(project_dir):
        content = read(path)
        for m in money_re.finditer(content):
            money_hits.append(
                f"{path.relative_to(project_dir)}:{line_of(content, m.start())} hardcoded {other} amount "
                f"(expected {args.currency})"
            )
    gate("G-03", f"currency consistent with {args.currency}", not money_hits, money_hits)

    # D — data contract -----------------------------------------------------
    products_src = read(project_dir / "src" / "data" / "products.ts")

    image_blocks = IMAGES_ARRAY_RE.findall(products_src)
    product_count = len(image_blocks)
    gate(
        "D-01",
        "at least 8 products",
        product_count >= 8,
        [f"found {product_count} products, need >= 8"],
    )

    same_pair = []
    for block in image_blocks:
        pairs = re.findall(r"'([^']+)'|\"([^\"]+)\"", block)
        flat = [a or b for a, b in pairs]
        if len(flat) >= 2 and flat[0] == flat[1]:
            same_pair.append(f"primary and secondary image are identical: {flat[0]}")
    gate("D-02", "primary/secondary images differ", not same_pair, same_pair)

    cat_keys = [k for k in CATEGORY_KEY_RE.findall(products_src) if k != "all"]
    generic = [k for k in cat_keys if re.fullmatch(r"category-[a-z0-9]+", k)]
    gate(
        "D-03",
        "at least 5 real categories",
        len(cat_keys) >= 5 and not generic,
        ([f"found {len(cat_keys)} categories, need >= 5"] if len(cat_keys) < 5 else [])
        + [f"generic category name: {g}" for g in generic],
    )

    types_src = read(project_dir / "src" / "types" / "index.ts")
    missing_fields = [f for f in REQUIRED_PRODUCT_FIELDS if not re.search(rf"\b{f}\??:", types_src)]
    gate(
        "D-04",
        "Product interface complete",
        not missing_fields,
        [f"Product is missing field: {f}" for f in missing_fields],
    )

    gate(
        "D-05",
        "PROMO_CODES exported",
        "PROMO_CODES" in products_src,
        ["src/data/products.ts has no PROMO_CODES"],
        warn_only=True,
    )

    # S — state -------------------------------------------------------------
    cart_src = read(project_dir / "src" / "store" / "cartStore.ts")
    missing_members = [m for m in CART_STORE_MEMBERS if m not in cart_src]
    gate(
        "S-01",
        "cart store contract",
        not missing_members,
        [f"cartStore.ts is missing: {', '.join(missing_members)}"] if missing_members else [],
    )
    gate(
        "S-02",
        "wishlist store persisted",
        "useWishlistStore" in cart_src and "persist" in cart_src,
        ["no persisted useWishlistStore found"],
    )

    # U — UX ----------------------------------------------------------------
    home_src = read(project_dir / "src" / "pages" / "HomePage.tsx")
    app_src = read(project_dir / "src" / "App.tsx")
    dup = "<AIChatWidget" in home_src and "<AIChatWidget" in app_src
    gate(
        "U-01",
        "no duplicated AI widget mount",
        not dup,
        ["AIChatWidget is mounted in both App.tsx and HomePage.tsx"],
    )

    hard_nav = []
    for path in iter_source_files(project_dir):
        content = read(path)
        for m in re.finditer(r"window\.location", content):
            hard_nav.append(f"{path.relative_to(project_dir)}:{line_of(content, m.start())} hard navigation")
    gate("U-02", "SPA routing (no window.location)", not hard_nav, hard_nav)

    ai_src = read(project_dir / "src" / "components" / "AIChatWidget.tsx")
    raw = len(re.findall(r"\bmatches\(|\.includes\(", ai_src))
    scenario_count = max(0, raw - 1) if "function matches(" in ai_src else raw
    gate(
        "U-03",
        "AI widget has >= 8 scenarios",
        scenario_count >= 8,
        [f"found {scenario_count} keyword scenarios, need >= 8"],
    )

    for rel, indicators in PAGE_INDICATORS.items():
        path = project_dir / rel
        if not path.exists():
            continue
        content = read(path)
        missing = [label for pattern, label in indicators if not re.search(pattern, content)]
        gate(
            f"U-04/{Path(rel).name}",
            f"{Path(rel).name} section coverage",
            not missing,
            [f"{rel} looks incomplete, missing: {', '.join(missing)}"] if missing else [],
            warn_only=True,
        )

    # T — theme & styling ---------------------------------------------------
    tw_src = read(project_dir / "tailwind.config.js")
    palettes = [p for p in ("brand", "fresh", "leaf", "accent") if re.search(rf"\b{p}:\s*\{{", tw_src)]
    gate(
        "T-01",
        "two color palettes defined",
        len(palettes) >= 2,
        [f"tailwind.config.js defines {len(palettes)} palette(s): {palettes or 'none'}"],
    )
    gate(
        "T-02",
        "palettes have a full scale",
        "50:" in tw_src and "900:" in tw_src,
        ["palette scale should span 50-900"],
        warn_only=True,
    )

    css_src = read(project_dir / "src" / "styles.css")
    missing_css = [c for c in REQUIRED_CSS_CLASSES if f".{c}" not in css_src]
    gate("T-03", "component classes defined", not missing_css, [f"styles.css is missing: {', '.join(missing_css)}"])

    gate(
        "T-04",
        "lucide-react dependency",
        '"lucide-react"' in read(project_dir / "package.json"),
        ["lucide-react missing from package.json"],
    )

    # L — language ----------------------------------------------------------
    html_src = read(project_dir / "index.html")
    lang_match = re.search(r'<html[^>]*lang="([^"]+)"', html_src)
    lang_value = lang_match.group(1) if lang_match else ""
    lang_ok = lang_value.startswith("zh") if args.lang.startswith("zh") else lang_value.startswith("en")
    gate(
        "L-01",
        f"index.html lang matches {args.lang}",
        lang_ok,
        [f'index.html lang="{lang_value}" but expected {args.lang}'],
    )

    # I — images ------------------------------------------------------------
    static_root = None
    for candidate in ("static", "public"):
        if (project_dir / candidate).exists():
            static_root = project_dir / candidate
            break

    broken_local: list[str] = []
    remote_urls: list[str] = []
    for block in image_blocks:
        for a, b in re.findall(r"'([^']+)'|\"([^\"]+)\"", block):
            url = a or b
            if url.startswith("/images/"):
                if static_root is None or not (static_root / url.lstrip("/")).exists():
                    broken_local.append(f"local image not found: {url}")
            elif url.startswith("http"):
                remote_urls.append(url)
    gate("I-01", "local images exist", not broken_local, broken_local)

    if args.check_images and remote_urls:
        unreachable = []
        for url in sorted(set(remote_urls)):
            try:
                req = urllib.request.Request(url, method="HEAD", headers={"User-Agent": "neway-validator"})
                with urllib.request.urlopen(req, timeout=10) as resp:  # noqa: S310
                    if resp.status != 200:
                        unreachable.append(f"{url} -> HTTP {resp.status}")
            except Exception as exc:  # noqa: BLE001
                unreachable.append(f"{url} -> {type(exc).__name__}")
        gate("I-02", "remote images reachable", not unreachable, unreachable)

    return errors, warnings, gates


# --------------------------------------------------------------------------- #
# Entry point
# --------------------------------------------------------------------------- #


def main() -> None:
    parser = argparse.ArgumentParser(description="Quality gate for Neway Commerce OS output.")
    parser.add_argument("project_dir", help="Path to the generated project directory.")
    parser.add_argument("--template", action="store_true", help="Validate templates/base itself.")
    parser.add_argument("--lang", default="zh-CN", help="Expected UI language (zh-CN / en).")
    parser.add_argument("--currency", default="CNY", choices=["CNY", "USD"], help="Expected currency.")
    parser.add_argument("--check-images", action="store_true", help="HEAD-request remote images.")
    parser.add_argument("--json", action="store_true", help="Emit a JSON report.")
    args = parser.parse_args()

    project_dir = Path(args.project_dir).resolve()
    if not project_dir.exists():
        print(f"Project not found: {project_dir}")
        raise SystemExit(1)

    errors, warnings, gates = run_gates(project_dir, args)

    if args.json:
        print(
            json.dumps(
                {
                    "project": str(project_dir),
                    "result": "FAIL" if errors else "PASS",
                    "errors": errors,
                    "warnings": warnings,
                    "gates": gates,
                },
                ensure_ascii=False,
                indent=2,
            )
        )
        raise SystemExit(1 if errors else 0)

    for entry in gates:
        print(f"[{entry['status']}] {entry['id']:<18} {entry['name']}")
        if entry["status"] != "PASS":
            for line in entry["detail"]:
                print(f"          - {line}")

    print()
    if errors:
        print(f"RESULT: FAIL — {len(errors)} error(s), {len(warnings)} warning(s). Do not deliver.")
    elif warnings:
        print(f"RESULT: PASS — 0 errors, {len(warnings)} warning(s). Review the warnings above.")
    else:
        print("RESULT: PASS — all gates clean.")

    raise SystemExit(1 if errors else 0)


if __name__ == "__main__":
    main()
